@import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=Rajdhani:wght@500;600;700&display=swap');
:root{--red:#e83f50;--gold:#ffbe55;--ink:#090b12;--ice:#dce7ef}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#050609;color:var(--ice);font-family:'Rajdhani',sans-serif}body{touch-action:none}#game-shell{position:relative;width:100vw;height:100dvh;min-height:500px;overflow:hidden;background:#090b12}canvas{display:block;width:100%;height:100%;image-rendering:pixelated}.screen{position:absolute;inset:0;display:none;align-items:center;justify-content:center;text-align:center;background:linear-gradient(90deg,rgba(5,6,9,.82),rgba(8,10,16,.25),rgba(5,6,9,.82));z-index:5}.screen.visible{display:flex}.title-mark{font-family:'Press Start 2P',monospace;text-shadow:5px 5px 0 #3a111b;letter-spacing:1px;color:#f24b57;font-size:clamp(23px,5vw,58px);line-height:1.55}.title-mark span{display:block;color:#e8e8d5;font-size:.55em;letter-spacing:8px}.tagline{margin:13px 0 38px;color:#aab1b9;letter-spacing:4px;text-transform:uppercase;font-size:clamp(12px,1.5vw,17px)}.start-card{border:1px solid rgba(220,231,239,.3);background:rgba(9,11,18,.78);padding:24px 30px 21px;box-shadow:0 0 0 5px rgba(8,10,15,.55),0 0 40px rgba(190,40,52,.13)}.start-card p{color:var(--gold);font-size:13px;letter-spacing:4px;margin:0 0 19px;font-weight:700}.start-card small,.pause-panel small{display:block;color:#89929b;margin-top:18px;font-size:13px;letter-spacing:1px}button{font:inherit;cursor:pointer;border:0;color:inherit}.start-card button,.victory-panel button,.pause-panel button{background:var(--red);padding:15px 23px;color:#fff;font-family:'Press Start 2P',monospace;font-size:11px;box-shadow:4px 4px 0 #7a202c;transition:.15s}.start-card button:hover,.victory-panel button:hover,.pause-panel button:hover{background:#ff5965;transform:translate(-2px,-2px);box-shadow:6px 6px 0 #7a202c}.pause-panel{background:rgba(8,10,16,.9);padding:35px 48px;border:1px solid #49515d;display:flex;flex-direction:column;align-items:center;gap:14px}.pause-panel span{font-family:'Press Start 2P';font-size:20px;color:var(--gold)}.pause-panel button{font-size:10px;padding:13px 20px}#hud{position:absolute;top:24px;left:30px;right:30px;display:flex;align-items:flex-start;justify-content:space-between;z-index:2;pointer-events:none;text-shadow:2px 2px #08090d}.hero-hud{display:flex;gap:10px;min-width:220px}.portrait{width:37px;height:37px;border:2px solid var(--red);color:var(--red);display:grid;place-items:center;font-size:22px;background:#111520}.label-row{display:flex;justify-content:space-between;font-size:12px;letter-spacing:1px}.label-row b{color:#e9e9dc}.bar{height:9px;width:210px;background:#252a32;margin-top:4px;border:1px solid #414a54;position:relative}.bar i{display:block;height:100%;transition:width .25s}.health i{background:linear-gradient(90deg,#9d2637,#ec4d58)}.devil{height:4px;margin-top:6px}.devil i{background:var(--gold)}.devil-label{font-size:8px;color:#b29b6c;letter-spacing:2px}.score-hud{text-align:center}.score-hud .label{font-size:10px;color:#84909a;letter-spacing:3px}.score-hud strong{display:block;color:var(--gold);font-family:'Press Start 2P';font-size:27px}.score-hud span:nth-of-type(2){font-size:9px;letter-spacing:2px;color:#a8b0b6}.score-hud b{display:block;color:#e9e5d7;font-family:'Press Start 2P';font-size:12px;margin-top:9px}.stage-hud{text-align:right;font-size:10px;letter-spacing:2px;color:#aeb8bf}.stage-hud b{display:block;color:#e8e4d7;font-size:13px;margin-top:5px}.game-message{position:absolute;top:27%;left:50%;transform:translateX(-50%);font-family:'Press Start 2P';font-size:clamp(12px,2vw,20px);color:var(--gold);text-shadow:3px 3px #41151c;opacity:0;z-index:3;white-space:nowrap;pointer-events:none}.game-message.show{animation:announce 1.8s ease-out both}@keyframes announce{0%{opacity:0;transform:translate(-50%,20px)}20%,70%{opacity:1;transform:translate(-50%,0)}100%{opacity:0;transform:translate(-50%,-20px)}}#combo{position:absolute;left:30px;bottom:32%;display:none;flex-direction:column;align-items:flex-start;z-index:2;text-shadow:3px 3px #111}.game-live #combo{display:flex}#combo b{font-family:'Press Start 2P';font-size:31px;color:#f1ece0}#combo span{font-size:11px;letter-spacing:4px;color:#a9b5bd}#combo em{font-family:'Press Start 2P';font-size:12px;color:var(--red);font-style:normal;margin-top:5px}.victory-panel{width:min(90%,560px);background:rgba(7,9,15,.93);border:1px solid #545b66;padding:42px 30px 35px;box-shadow:0 0 80px rgba(219,54,67,.16)}.victory-kicker{color:var(--gold);letter-spacing:5px;font-weight:700;font-size:12px}.victory-panel h1{font-family:'Press Start 2P';font-size:clamp(19px,4vw,36px);color:#e8e6d9;margin:20px 0 13px}.victory-panel p{color:#9ba5ae;margin-bottom:26px}.result-line{border-top:1px solid #323a44;border-bottom:1px solid #323a44;padding:15px 0;margin-bottom:28px;display:flex;justify-content:space-between;color:#939da5;letter-spacing:2px}.result-line b{color:#f2e7cb;font-family:'Press Start 2P'}#touch-controls{position:absolute;bottom:22px;left:22px;right:22px;display:none;justify-content:space-between;align-items:end;z-index:4}.dpad{display:flex;flex-direction:column;align-items:center;gap:2px}.dpad div{display:flex;gap:2px}.dpad button,.action-pad button{width:45px;height:38px;background:rgba(26,31,42,.72);border:1px solid rgba(220,231,239,.27);color:#d7dce0;border-radius:4px;font-size:16px}.dpad>button{margin-bottom:0}.action-pad{display:flex;gap:10px;align-items:end}.action-pad button{border-radius:50%;width:58px;height:58px;font-family:'Press Start 2P';font-size:18px}.action-pad .attack{background:rgba(191,42,57,.7);border-color:#f05a64}.action-pad .evade{background:rgba(169,127,45,.55);border-color:#e3ba63}@media(max-width:700px){#hud{top:12px;left:14px;right:14px}.bar{width:145px}.stage-hud{display:none}.score-hud{position:absolute;right:0;top:0}.hero-hud{min-width:0}.portrait{width:30px;height:30px;font-size:15px}.label-row{font-size:10px}.score-hud strong{font-size:21px}#touch-controls{display:flex}.game-live #touch-controls{display:flex}#combo{left:15px;bottom:28%;}.start-card{padding:20px 16px}.start-card small{max-width:230px;line-height:1.5}.title-mark{font-size:25px}}
@media(min-width:701px){.game-live #touch-controls{display:none}}

const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
let W=960,H=540,scale=1,keys={},running=false,paused=false,last=0,score=0,style=0,combo=0,comboTimer=0,spawned=0,shake=0;
const player={x:170,y:395,w:28,h:56,vx:0,vy:0,face:1,onGround:true,hp:100,devil:22,attack:0,attackStep:0,inv:0,evade:0,anim:0};
let enemies=[],particles=[],slashes=[],texts=[];
const ranks=[['D','DULL'],['C','CRIMSON'],['B','BRUTAL'],['A','ARDENT'],['S','STYLISH'],['SS','SAVAGE']];
function fit(){const d=Math.min(innerWidth/W,innerHeight/H);canvas.width=W;canvas.height=H;scale=d;canvas.style.width=`${W*d}px`;canvas.style.height=`${H*d}px`}addEventListener('resize',fit);fit();
function reset(){Object.assign(player,{x:170,y:395,vx:0,vy:0,onGround:true,hp:100,devil:22,attack:0,attackStep:0,inv:0,evade:0,anim:0,face:1});enemies=[];particles=[];slashes=[];texts=[];score=0;style=0;combo=0;comboTimer=0;spawned=0;addEnemy(590,410,'scourge');addEnemy(730,410,'scourge');addEnemy(870,410,'warden');updateHud()}
function addEnemy(x,y,type='scourge'){enemies.push({x,y,w:type==='warden'?35:27,h:type==='warden'?63:47,hp:type==='warden'?90:42,max:type==='warden'?90:42,type,face:-1,stun:0,attack:0,dead:0,flash:0,phase:Math.random()*6})}
function start(){reset();running=true;document.getElementById('start-screen').classList.remove('visible');document.getElementById('game-shell').classList.add('game-live');say('MISSION START');last=performance.now();requestAnimationFrame(loop)}
function say(t){const m=document.getElementById('message');m.textContent=t;m.classList.remove('show');void m.offsetWidth;m.classList.add('show')}
function updateHud(){document.getElementById('health-fill').style.width=Math.max(0,player.hp)+'%';document.getElementById('devil-fill').style.width=Math.min(100,player.devil)+'%';document.getElementById('health-text').textContent=`${Math.ceil(player.hp)} / 100`;document.getElementById('score').textContent=String(score).padStart(6,'0');let r=ranks[Math.min(5,Math.floor(style/22))];document.getElementById('style-rank').textContent=r[0];document.getElementById('style-name').textContent=r[1];document.getElementById('combo-count').textContent=combo;document.getElementById('combo-word').textContent=combo>35?'GODLIKE':combo>22?'SSS—SAVAGE':combo>13?'STYLISH':combo>5?'CRIMSON':'—'}
function loop(t){if(!running)return;const dt=Math.min(.033,(t-last)/1000);last=t;if(!paused){update(dt);draw()}requestAnimationFrame(loop)}
function update(dt){if(shake>0)shake-=dt;player.anim+=dt;if(player.inv>0)player.inv-=dt;if(player.evade>0)player.evade-=dt;if(comboTimer>0)comboTimer-=dt;else if(combo){combo=0;style=Math.max(0,style-4);updateHud()}
  const left=keys.ArrowLeft||keys.a, right=keys.ArrowRight||keys.d, jump=keys.ArrowUp||keys.w||keys[' '];if(!player.evade){player.vx=(right?180:0)-(left?180:0);if(player.vx)player.face=player.vx>0?1:-1;player.x+=player.vx*dt;if(jump&&player.onGround){player.vy=-360;player.onGround=false;keys.ArrowUp=keys.w=keys[' ']=false}} else player.vx=player.face*310;
  player.vy+=950*dt;player.y+=player.vy*dt;if(player.y>=395){player.y=395;player.vy=0;player.onGround=true}player.x=Math.max(35,Math.min(925,player.x));
  if(player.attack>0){player.attack-=dt;if(player.attack<.09&&player.attackStep===1)hitCheck();}for(const e of enemies){if(e.dead){e.dead+=dt;continue}if(e.stun>0)e.stun-=dt;if(e.flash>0)e.flash-=dt;e.phase+=dt;if(!e.stun){const dx=player.x-e.x;if(Math.abs(dx)>55)e.x+=Math.sign(dx)*((e.type==='warden'?38:55))*dt;e.face=dx>0?1:-1;if(Math.abs(dx)<55&&!player.evade){e.attack+=dt;if(e.attack>.9){damagePlayer(e.type==='warden'?15:9);e.attack=0}}} }
  enemies=enemies.filter(e=>e.dead<.6);if(enemies.filter(e=>!e.dead).length===0){if(spawned<2){spawned++;say(spawned===1?'MORE DEMONS APPROACH':'THE WARDEN AWAKENS');setTimeout(()=>{if(running){if(spawned===1){addEnemy(760,410,'scourge');addEnemy(850,410,'scourge');addEnemy(620,410,'scourge')}else addEnemy(820,410,'warden')}},650)}else win()}
  particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=260*dt;p.life-=dt});particles=particles.filter(p=>p.life>0);slashes.forEach(s=>s.life-=dt);slashes=slashes.filter(s=>s.life>0);texts.forEach(a=>{a.y-=25*dt;a.life-=dt});texts=texts.filter(a=>a.life>0);updateHud()}
function damagePlayer(n){if(player.inv>0)return;player.hp-=n;player.inv=.75;shake=.2;burst(player.x,player.y-28,'#e84657',8);if(player.hp<=0){player.hp=100;score=Math.max(0,score-1200);say('REVIVED BY THE ASHES')}}
function hitCheck(){const reach=player.face>0?{l:player.x-5,r:player.x+66}:{l:player.x-66,r:player.x+5};let hit=false;for(const e of enemies){if(e.dead||e.stun>0)continue;if(e.x+e.w/2>reach.l&&e.x-e.w/2<reach.r&&Math.abs(e.y-player.y)<45){const dmg=player.attackStep===3?28:player.attackStep===2?18:12;e.hp-=dmg;e.stun=.22;e.flash=.14;hit=true;combo++;comboTimer=2;style=Math.min(110,style+(player.attackStep===3?8:4));score+=dmg*10+combo*3;texts.push({x:e.x,y:e.y-60,text:`+${dmg}`,life:.7,color:'#ffca63'});burst(e.x,e.y-25,player.attackStep===3?'#ffc45c':'#e64c5b',player.attackStep===3?14:7);if(e.hp<=0){e.dead=.01;score+=e.type==='warden'?800:250;style+=12;say(e.type==='warden'?'WARDEN VANQUISHED':'DEMON PURGED')}}}if(hit){player.devil=Math.min(100,player.devil+4);shake=.09;slashes.push({x:player.x+player.face*34,y:player.y-30,face:player.face,life:.2,big:player.attackStep===3})}}
function attack(){if(!running||paused||player.attack>0||player.evade>0)return;player.attack=.25;player.attackStep=(player.attackStep%3)+1;setTimeout(()=>{player.attackStep=0},270)}
function evade(){if(!running||paused||player.evade>0)return;player.evade=.3;player.inv=.42;burst(player.x,player.y-20,'#a8c3ce',6)}
function burst(x,y,c,n){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*180,vy:-Math.random()*170-30,life:.25+Math.random()*.4,color:c,size:2+Math.random()*4})}
function draw(){ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*7,(Math.random()-.5)*5);drawBg();drawFloor();for(const e of enemies)drawEnemy(e);drawPlayer();for(const s of slashes)drawSlash(s);for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/.5);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)}ctx.globalAlpha=1;for(const a of texts){ctx.globalAlpha=a.life/.7;ctx.font='bold 14px Rajdhani';ctx.fillStyle=a.color;ctx.fillText(a.text,a.x,a.y)}ctx.restore()}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}
function drawBg(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#111a2b');g.addColorStop(.58,'#171725');g.addColorStop(1,'#0b0c13');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.fillStyle='#252a3b';ctx.beginPath();ctx.arc(760,112,68,0,7);ctx.fill();ctx.fillStyle='#ced4cf';ctx.beginPath();ctx.arc(760,112,50,0,7);ctx.fill();rect(0,260,W,3,'#36374b');for(let x=0;x<1000;x+=110){rect(x,120+(x%4)*19,7,140,'#131a2a');rect(x+7,120+(x%4)*19,55,7,'#1e2638')}rect(0,285,W,3,'#471c29');for(let x=0;x<960;x+=32){rect(x,288,2,109,'#10131c');}}
function drawFloor(){rect(0,398,W,142,'#100f17');for(let x=-20;x<1000;x+=40){ctx.strokeStyle='#28212c';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,398);ctx.lineTo(x+Math.sin(x)*20,540);ctx.stroke()}ctx.strokeStyle='#71303b';ctx.beginPath();ctx.moveTo(0,398);ctx.lineTo(W,398);ctx.stroke();for(let x=25;x<960;x+=90){rect(x,430,45,2,'#26202b')}}
function drawPlayer(){if(player.inv>0&&Math.floor(player.inv*18)%2===0)return;let x=player.x,y=player.y;ctx.save();if(player.face<0){ctx.translate(x*2,0);ctx.scale(-1,1);x=0}rect(x-14,y-55,28,44,'#a72f43');rect(x-11,y-39,22,28,'#d9d3c3');rect(x-13,y-12,9,13,'#27314a');rect(x+4,y-12,9,13,'#27314a');rect(x-12,y-62,24,10,'#161b2c');rect(x-15,y-58,6,25,'#c83b4b');rect(x+5,y-60,11,5,'#c83b4b');rect(x-9,y-48,4,3,'#f1bd76');rect(x+3,y-48,4,3,'#f1bd76');rect(x+13,y-32,21,3,'#b6bbc3');ctx.restore();if(player.attack>0){rect(player.x+player.face*20-2,player.y-40,player.face*34,3,'#f5e1b5')}}
function drawEnemy(e){if(e.dead)return;const x=e.x,y=e.y;ctx.save();if(e.face<0){ctx.translate(x*2,0);ctx.scale(-1,1)}let col=e.flash>0?'#fff0c1':e.type==='warden'?'#392d48':'#482b42';rect(x-18,y-58,36,55,col);rect(x-14,y-70,28,18,e.type==='warden'?'#554460':'#683044');rect(x-12,y-51,24,10,'#202234');rect(x-8,y-48,5,3,'#ef594f');rect(x+5,y-48,5,3,'#ef594f');rect(x-20,y-8,10,9,'#171827');rect(x+10,y-8,10,9,'#171827');rect(x-25,y-48,8,4,'#a33d4b');rect(x+17,y-48,8,4,'#a33d4b');if(e.hp<e.max){rect(x-21,y-78,42,3,'#1c1d27');rect(x-21,y-78,42*(e.hp/e.max),3,'#c83d4b')}ctx.restore()}
function drawSlash(s){ctx.save();ctx.translate(s.x,s.y);ctx.scale(s.face,1);ctx.globalAlpha=Math.min(1,s.life/.2);ctx.strokeStyle=s.big?'#fff1c4':'#e84c5c';ctx.lineWidth=s.big?5:3;ctx.beginPath();ctx.arc(0,0,s.big?42:31,-1.15,.85);ctx.stroke();ctx.restore()}
function win(){running=false;document.getElementById('final-score').textContent=String(score).padStart(6,'0');document.getElementById('victory').classList.add('visible');document.getElementById('game-shell').classList.remove('game-live')}
function togglePause(){if(!running)return;paused=!paused;document.getElementById('pause-screen').classList.toggle('visible',paused)}
addEventListener('keydown',e=>{keys[e.key]=true;if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();if(e.key==='j'||e.key==='J'||e.key===' ')attack();if(e.key==='k'||e.key==='K')evade();if(e.key==='p'||e.key==='P')togglePause()});addEventListener('keyup',e=>keys[e.key]=false);
document.getElementById('start-button').onclick=start;document.getElementById('retry-button').onclick=()=>{document.getElementById('victory').classList.remove('visible');start()};document.getElementById('resume-button').onclick=togglePause;
document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key,map={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'};b.addEventListener('pointerdown',e=>{e.preventDefault();keys[map[k]]=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,()=>keys[map[k]]=false))});document.querySelector('[data-action="attack"]').addEventListener('pointerdown',attack);document.querySelector('[data-action="evade"]').addEventListener('pointerdown',evade);

